public Mappings diffStructure(String tableName, Mappings mappings){
    // Determine the current index mappings
    Mappings currentMappings = getMappings(tableName);

    // Create a new Mappings object to store the differences
    Mappings diffMappings = new Mappings();

    // Iterate over the current mappings and compare with the input mappings
    for (String field : currentMappings.getFields()){
        if (!mappings.containsField(field)) {
            // Add the missing field and its type to the diff mappings
            diffMappings.addField(field, currentMappings.getFieldType(field));
        }
    }

    // Remove the _source config from the diff mappings
    diffMappings.removeField("_source");

    return diffMappings;
}

