public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    List<String> lines = Files.readAllLines(file.toPath());
    for (String line : lines) {
        Matcher matcher = THREAD_SNAPSHOT_PATTERN.matcher(line);
        if (matcher.matches()) {
            String threadName = matcher.group(1);
            long startTime = Long.parseLong(matcher.group(2));
            long endTime = Long.parseLong(matcher.group(3));
            long sampleCount = Long.parseLong(matcher.group(4));
            String stackTrace = matcher.group(5);
            boolean isDeadlocked = Boolean.parseBoolean(matcher.group(6));

            ThreadSnapshot threadSnapshot = new ThreadSnapshot(threadName, startTime, endTime, sampleCount, stackTrace, isDeadlocked);
            threadSnapshots.add(threadSnapshot);
        }
    }
    return threadSnapshots;
}

