private void pop(final String descriptor) {
    int numParameters = 0;
    int numArguments = 0;

    if (descriptor.startsWith("(")) {
        // Method descriptor, count the number of parameters
        numParameters = descriptor.indexOf(")") - 1;
        for (int i = 1; i < numParameters; i++) {
            if (descriptor.charAt(i) == 'L') {
                // Parameter is an object, so it requires a pop
                numArguments++;
            } else if (descriptor.charAt(i) == '[') {
                // Parameter is an array, so it requires a pop
                numArguments++;
            }
        }
    }

    // Pop the relevant number of arguments from the stack
    for (int i = 0; i < numArguments; i++) {
        pop();
    }
}

