public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    // Get the UTF-8 bytes from the string
    final byte[] utf8Bytes = str.toString().getBytes(StandardCharsets.UTF_8);

    // Write the length of the UTF-8 bytes as a 16-bit integer
    lb.writeShort((short) utf8Bytes.length);

    // Write the UTF-8 bytes into the LinkedBuffer
    for (int i = 0; i < utf8Bytes.length; i++) {
        lb.writeByte(utf8Bytes[i]);
    }

    return lb;
}

